def resolve_library_id(libraryName, **_extra):
    import json, os, datetime, time, difflib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0462000" if __import__("os").path.isdir("./environment_mix/0462000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat()

    def _ensure_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _rate_check(endpoint, limit=60, window_seconds=60):
        _ensure_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = now_dt - datetime.timedelta(seconds=window_seconds)
        used = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            dt = _parse_ts(r.get("timestamp"))
            if dt and dt >= cutoff:
                used += 1
        return (used >= limit), {"limit": limit, "window_seconds": window_seconds, "used": used}

    def _log(endpoint, status, error_code=None, meta=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": now,
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    endpoint = "resolve-library-id"

    limited, rl = _rate_check(endpoint, limit=60, window_seconds=60)
    if limited:
        _log(endpoint, "error", "RATE_LIMIT", {"rate_limit": rl})
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit=rl)

    if libraryName is None or not isinstance(libraryName, str):
        _log(endpoint, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "libraryName is required and must be a string.")
    q_raw = libraryName
    q = q_raw.strip()
    if q == "":
        _log(endpoint, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "libraryName must be a non-empty string.")

    q_norm = q.lower().strip()
    q_norm = re.sub(r"\s+", " ", q_norm)

    libraries = _load("libraries.json")
    if isinstance(libraries, dict) and "rows" in libraries and isinstance(libraries["rows"], list):
        libraries = libraries["rows"]
    if not isinstance(libraries, list):
        libraries = []

    aliases = _load("library_aliases.json")
    if isinstance(aliases, dict) and "rows" in aliases and isinstance(aliases["rows"], list):
        aliases = aliases["rows"]
    if not isinstance(aliases, list):
        aliases = []

    versions = _load("library_versions.json")
    if isinstance(versions, dict) and "rows" in versions and isinstance(versions["rows"], list):
        versions = versions["rows"]
    if not isinstance(versions, list):
        versions = []

    lib_by_id = {r.get("id"): r for r in libraries if isinstance(r, dict) and isinstance(r.get("id"), str)}
    vers_by_lib = {}
    for v in versions:
        if not isinstance(v, dict):
            continue
        lid = v.get("library_id")
        if not isinstance(lid, str):
            continue
        vers_by_lib.setdefault(lid, []).append(v)

    # Only active libraries unless explicitly configured; no tool param for that, so enforce active.
    def _lib_is_active(librow):
        return isinstance(librow, dict) and librow.get("status") == "active"

    # Scoring:
    # 1) alias exact match (highest)
    # 2) alias popularity_score
    # 3) display_name similarity (difflib ratio)
    # also allow substring matches at lower weight.
    scored = {}  # library_id -> best_score and details
    details = {}  # library_id -> detail dict for output

    def _display_similarity(name):
        if not isinstance(name, str) or not name:
            return 0.0
        a = name.lower().strip()
        a = re.sub(r"\s+", " ", a)
        return difflib.SequenceMatcher(None, q_norm, a).ratio()

    # Display-name matches
    for lib in libraries:
        if not _lib_is_active(lib):
            continue
        lid = lib.get("id")
        if not isinstance(lid, str):
            continue
        dn = lib.get("display_name") or ""
        cn = lib.get("canonical_library_id")
        if not isinstance(cn, str):
            continue
        sim = _display_similarity(dn)
        # Boost substring-ish matches a bit
        dn_norm = re.sub(r"\s+", " ", str(dn).lower().strip())
        sub = 1.0 if (q_norm in dn_norm or dn_norm in q_norm) and dn_norm else 0.0
        score = sim * 100.0 + sub * 10.0
        if score > 0:
            prev = scored.get(lid, float("-inf"))
            if score > prev:
                scored[lid] = score
                details[lid] = {"best_match": "display_name", "alias": None, "popularity_score": None, "display_similarity": sim}

    # Alias matches
    for al in aliases:
        if not isinstance(al, dict):
            continue
        if al.get("status") != "active":
            continue
        lid = al.get("library_id")
        if not isinstance(lid, str) or lid not in lib_by_id:
            continue
        lib = lib_by_id.get(lid)
        if not _lib_is_active(lib):
            continue

        alias_text = al.get("alias_text")
        if not isinstance(alias_text, str):
            continue
        alias_norm = alias_text.lower().strip()
        alias_norm = re.sub(r"\s+", " ", alias_norm)

        pop = al.get("popularity_score")
        try:
            pop_val = float(pop)
            if pop_val < 0:
                continue
        except Exception:
            pop_val = 0.0

        exact = 1.0 if alias_norm == q_norm else 0.0
        # substring (weaker than exact)
        contains = 1.0 if (q_norm and (q_norm in alias_norm or alias_norm in q_norm)) else 0.0

        # Primary rank: exact match
        # Then: popularity_score
        # Then: display_name similarity
        disp_sim = _display_similarity(lib.get("display_name") or "")
        score = exact * 1_000_000.0 + contains * 10_000.0 + pop_val * 100.0 + disp_sim * 10.0

        prev = scored.get(lid, float("-inf"))
        if score > prev:
            scored[lid] = score
            details[lid] = {
                "best_match": "alias_exact" if exact else ("alias_contains" if contains else "alias"),
                "alias": alias_text,
                "popularity_score": pop_val,
                "display_similarity": disp_sim,
            }

    # Build sorted results
    ranked = sorted(scored.items(), key=lambda kv: kv[1], reverse=True)

    results = []
    for lid, score in ranked[:50]:  # not paged; cap for sanity
        lib = lib_by_id.get(lid)
        if not lib or not _lib_is_active(lib):
            continue
        canonical = lib.get("canonical_library_id")
        if not isinstance(canonical, str):
            continue

        # Include canonical and known versioned variants (active versions) when present
        version_ids = []
        for v in vers_by_lib.get(lid, []):
            if not isinstance(v, dict):
                continue
            if v.get("status") != "active":
                continue
            c7id = v.get("context7_compatible_library_id")
            if isinstance(c7id, str) and c7id:
                version_ids.append(c7id)

        results.append({
            "canonical_library_id": canonical,
            "display_name": lib.get("display_name"),
            "description": lib.get("description"),
            "homepage_url": lib.get("homepage_url"),
            "matched_by": details.get(lid, {}).get("best_match"),
            "matched_alias": details.get(lid, {}).get("alias"),
            "popularity_score": details.get(lid, {}).get("popularity_score"),
            "versioned_library_ids": version_ids,
        })

    _log(endpoint, "ok", None, {"query": q_raw, "returned": len(results), "rate_limit": rl})
    return {"matches": results}

def get_library_docs(context7CompatibleLibraryID, topic=None, tokens=None, **_extra):
    import json, os, datetime, time, difflib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0462000" if __import__("os").path.isdir("./environment_mix/0462000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _ensure_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _log(endpoint, status, error_code=None, meta=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": now,
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_rate_limit(endpoint, limit=60, window_seconds=60):
        _ensure_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=window_seconds)
        c = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            dt = _parse_ts(r.get("timestamp"))
            if dt and dt >= cutoff:
                c += 1
        return c >= limit, {"limit": limit, "window_seconds": window_seconds, "used": c}

    limited, rl_meta = _check_rate_limit("get-library-docs")
    if limited:
        _log("get-library-docs", "error", "RATE_LIMIT", meta=rl_meta)
        return _err("RATE_LIMIT", "Rate limit exceeded.", **rl_meta)

    # Validation (relaxed to accept IDs present in store: can be ctx7_lib_* id OR '/org/project' OR '/org/project/version')
    if not isinstance(context7CompatibleLibraryID, str) or not context7CompatibleLibraryID.strip():
        _log("get-library-docs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "context7CompatibleLibraryID must be a non-empty string.")

    if topic is not None and not isinstance(topic, str):
        _log("get-library-docs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "topic must be a string when provided.")

    if tokens is None:
        tokens_cap = 10000
    else:
        try:
            tokens_cap = float(tokens)
        except Exception:
            _log("get-library-docs", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tokens must be a number.")
        if tokens_cap != tokens_cap:  # NaN
            _log("get-library-docs", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tokens must be a number.")
        if tokens_cap.is_integer():
            tokens_cap = int(tokens_cap)
        else:
            tokens_cap = int(tokens_cap)  # floor like many services do
    if not isinstance(tokens_cap, int):
        _log("get-library-docs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tokens must be a number.")
    if tokens_cap < 1 or tokens_cap > 100000:
        _log("get-library-docs", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tokens must be within [1, 100000].", min=1, max=100000, provided=tokens)

    libraries = _load("libraries.json")
    versions = _load("library_versions.json")
    sources = _load("doc_sources.json")
    chunks = _load("doc_chunks.json")
    if not isinstance(libraries, list): libraries = []
    if not isinstance(versions, list): versions = []
    if not isinstance(sources, list): sources = []
    if not isinstance(chunks, list): chunks = []

    libs_by_id = {l.get("id"): l for l in libraries if isinstance(l, dict) and isinstance(l.get("id"), str)}
    libs_by_canon = {}
    for l in libraries:
        if not isinstance(l, dict):
            continue
        cid = l.get("canonical_library_id")
        if isinstance(cid, str) and isinstance(l.get("id"), str):
            libs_by_canon[cid] = l

    vers_by_id = {v.get("id"): v for v in versions if isinstance(v, dict) and isinstance(v.get("id"), str)}
    vers_by_ctxid = {}
    for v in versions:
        if not isinstance(v, dict):
            continue
        cid = v.get("context7_compatible_library_id")
        if isinstance(cid, str) and isinstance(v.get("id"), str):
            vers_by_ctxid[cid] = v

    raw_id = context7CompatibleLibraryID.strip()

    lib = None
    ver = None
    library_id = None
    library_version_id = None
    resolved_ctxid = None

    if raw_id.startswith("/"):
        parts = [p for p in raw_id.split("/") if p]
        if len(parts) == 2:
            resolved_ctxid = f"/{parts[0]}/{parts[1]}"
            lib = libs_by_canon.get(resolved_ctxid)
            if not lib:
                _log("get-library-docs", "error", "NOT_FOUND", meta={"provided": raw_id})
                return _err("NOT_FOUND", "No library exists for the provided Context7-compatible ID.", provided=raw_id)
            library_id = lib.get("id")
            # choose default version if exists else unversioned docs
            default_ver = None
            for v in versions:
                if isinstance(v, dict) and v.get("library_id") == library_id and v.get("is_default") is True and v.get("status") == "active":
                    default_ver = v
                    break
            if default_ver:
                ver = default_ver
                library_version_id = ver.get("id")
        elif len(parts) == 3:
            resolved_ctxid = f"/{parts[0]}/{parts[1]}/{parts[2]}"
            ver = vers_by_ctxid.get(resolved_ctxid)
            if not ver:
                _log("get-library-docs", "error", "NOT_FOUND", meta={"provided": raw_id})
                return _err("NOT_FOUND", "No library version exists for the provided Context7-compatible ID.", provided=raw_id)
            library_id = ver.get("library_id")
            library_version_id = ver.get("id")
            lib = libs_by_id.get(library_id)
            if not lib:
                _log("get-library-docs", "error", "NOT_FOUND", meta={"provided": raw_id})
                return _err("NOT_FOUND", "Library referenced by the version was not found.", provided=raw_id)
        else:
            _log("get-library-docs", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "context7CompatibleLibraryID must be in the form '/org/project' or '/org/project/version'.", provided=raw_id)
    else:
        # Accept library primary key ids present in store (audit requires this relaxation)
        lib = libs_by_id.get(raw_id)
        if not lib:
            _log("get-library-docs", "error", "NOT_FOUND", meta={"provided": raw_id})
            return _err("NOT_FOUND", "No library exists for the provided ID.", provided=raw_id)
        library_id = lib.get("id")
        resolved_ctxid = lib.get("canonical_library_id")
        default_ver = None
        for v in versions:
            if isinstance(v, dict) and v.get("library_id") == library_id and v.get("is_default") is True and v.get("status") == "active":
                default_ver = v
                break
        if default_ver:
            ver = default_ver
            library_version_id = ver.get("id")

    # sources must be ready; chunks must be active; and must match selected library/version boundary
    ready_source_ids = set()
    for s in sources:
        if not isinstance(s, dict):
            continue
        if s.get("library_id") != library_id:
            continue
        if s.get("ingest_status") != "ready":
            continue
        # enforce boundary: versioned call requires same version id; unversioned-with-default uses that version id; unversioned-without-default uses null
        if library_version_id is None:
            if s.get("library_version_id") is not None:
                continue
        else:
            if s.get("library_version_id") != library_version_id:
                continue
        sid = s.get("id")
        if isinstance(sid, str):
            ready_source_ids.add(sid)

    # Assemble candidate chunks
    tnorm = None
    if isinstance(topic, str) and topic.strip():
        tnorm = " ".join(topic.strip().lower().split())

    candidates = []
    for c in chunks:
        if not isinstance(c, dict):
            continue
        if c.get("status") != "active":
            continue
        if c.get("doc_source_id") not in ready_source_ids:
            continue
        if c.get("library_id") != library_id:
            continue
        if library_version_id is None:
            if c.get("library_version_id") is not None:
                continue
        else:
            if c.get("library_version_id") != library_version_id:
                continue

        labels = c.get("topic_labels")
        if not isinstance(labels, list):
            labels = []
        labels_norm = []
        for lb in labels:
            if isinstance(lb, str):
                labels_norm.append(" ".join(lb.strip().lower().split()))

        content = c.get("content")
        if not isinstance(content, str):
            continue

        # scoring: topic label match boosts; otherwise fall back to title/content similarity
        score = 0.0
        if tnorm:
            if tnorm in labels_norm:
                score += 2.0
            else:
                # mild similarity
                title = str(c.get("title") or "")
                score += 0.5 * difflib.SequenceMatcher(None, tnorm, " ".join(title.lower().split())).ratio()
                score += 0.3 * difflib.SequenceMatcher(None, tnorm, content[:800].lower()).ratio()
        # Stable base: earlier chunk_order first
        candidates.append((score, c))

    # Rank (topic score desc, then url, then chunk_order)
    def _sort_key(item):
        score, c = item
        url = str(c.get("url") or "")
        try:
            order = int(c.get("chunk_order") or 0)
        except Exception:
            order = 0
        return (-float(score), url, order)

    candidates.sort(key=_sort_key)

    # Token-limited assembly
    chosen = []
    used = 0
    for score, c in candidates:
        try:
            tc = int(c.get("token_count") or 0)
        except Exception:
            tc = 0
        if tc < 0:
            tc = 0
        if used == 0 and tc > tokens_cap:
            # best-effort: allow first chunk even if it exceeds cap, but truncate by skipping others
            chosen.append(c)
            used += tc
            break
        if used + tc <= tokens_cap:
            chosen.append(c)
            used += tc
        if used >= tokens_cap:
            break

    # Produce extract
    extract_parts = []
    for c in chosen:
        url = c.get("url")
        title = c.get("title")
        content = c.get("content") or ""
        header = ""
        if isinstance(title, str) and title.strip():
            header = title.strip()
        elif isinstance(url, str) and url.strip():
            header = url.strip()
        if header:
            extract_parts.append(f"# {header}\n{content}".strip())
        else:
            extract_parts.append(str(content).strip())

    body = "\n\n---\n\n".join([p for p in extract_parts if p])

    resp = {
        "context7CompatibleLibraryID": resolved_ctxid if isinstance(resolved_ctxid, str) else raw_id,
        "library": lib,
        "library_version": ver,
        "topic": topic,
        "tokens_requested": tokens_cap,
        "tokens_used": used,
        "chunks": [{"id": c.get("id"), "url": c.get("url"), "title": c.get("title"), "token_count": c.get("token_count"), "topic_labels": c.get("topic_labels")} for c in chosen],
        "content": body,
    }

    _log("get-library-docs", "ok", meta={"library_id": library_id, "library_version_id": library_version_id, "chunks": len(chosen), "tokens_used": used, "tokens_cap": tokens_cap})
    return resp

def list_libraries(query=None, status=None, org=None, project=None, keyword=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64, difflib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0462000" if __import__("os").path.isdir("./environment_mix/0462000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _log(status_s, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        rid = f"req_{int(time.time()*1000)}_{os.getpid()}"
        row = {
            "id": rid,
            "endpoint": "list-libraries",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limited(endpoint, limit=60, window_seconds=60):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        cutoff = now - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for r in logs:
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        return cnt >= limit

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            obj = json.loads(s)
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
        except Exception:
            return None
        return None

    def _encode_cursor(off):
        payload = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    start = time.time()

    if _rate_limited("list-libraries"):
        latency = int((time.time() - start) * 1000)
        _log("error", latency, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Validate inputs
    if query is not None and (not isinstance(query, str)):
        latency = int((time.time() - start) * 1000)
        _log("error", latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a string")

    allowed_status = {"active", "deprecated", "blocked", "any", None}
    if status not in allowed_status:
        latency = int((time.time() - start) * 1000)
        _log("error", latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deprecated, blocked, any")

    if org is not None and not isinstance(org, str):
        latency = int((time.time() - start) * 1000)
        _log("error", latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "org must be a string")

    if project is not None and not isinstance(project, str):
        latency = int((time.time() - start) * 1000)
        _log("error", latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project must be a string")

    if keyword is not None and not isinstance(keyword, str):
        latency = int((time.time() - start) * 1000)
        _log("error", latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "keyword must be a string")

    if limit is None:
        lim = 50
    else:
        if not isinstance(limit, int) or isinstance(limit, bool):
            latency = int((time.time() - start) * 1000)
            _log("error", latency, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            latency = int((time.time() - start) * 1000)
            _log("error", latency, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be within [1, 200]")
        lim = limit

    allowed_sort = {"relevance", "updated_at_desc", "created_at_desc", "display_name_asc", None}
    if sort not in allowed_sort:
        latency = int((time.time() - start) * 1000)
        _log("error", latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort must be one of: relevance, updated_at_desc, created_at_desc, display_name_asc")

    off = 0
    if cursor is not None:
        off = _decode_cursor(cursor)
        if off is None:
            latency = int((time.time() - start) * 1000)
            _log("error", latency, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    libs = _load("libraries.json")
    qn = query.lower().strip() if isinstance(query, str) and query.strip() else None
    kn = keyword.lower().strip() if isinstance(keyword, str) and keyword.strip() else None

    # Filter
    filtered = []
    for l in libs:
        if not isinstance(l, dict):
            continue

        if status is None:
            st_filter = "active"
        else:
            st_filter = status
        if st_filter != "any" and l.get("status") != st_filter:
            continue

        if org is not None and l.get("org") != org:
            continue
        if project is not None and l.get("project") != project:
            continue

        if kn:
            kws = l.get("keywords")
            if not isinstance(kws, list):
                continue
            kws_norm = [str(x).lower().strip() for x in kws if x is not None]
            if kn not in kws_norm:
                continue

        if qn:
            disp = l.get("display_name") or ""
            desc = l.get("description") or ""
            kws = l.get("keywords")
            blob = (str(disp) + " " + str(desc)).lower()
            hit = (qn in blob)
            if not hit and isinstance(kws, list):
                kws_norm = " ".join([str(x).lower().strip() for x in kws if x is not None])
                hit = (qn in kws_norm)
            if not hit:
                continue

        filtered.append(l)

    # Sorting
    if sort is None:
        sort_eff = "relevance" if qn else "updated_at_desc"
    else:
        sort_eff = sort

    def _relevance_score(l):
        if not qn:
            return 0.0
        disp = (l.get("display_name") or "").lower()
        kws = l.get("keywords")
        kws_s = ""
        if isinstance(kws, list):
            kws_s = " ".join([str(x).lower().strip() for x in kws if x is not None])
        text = (disp + " " + kws_s).strip()
        if not text:
            return 0.0
        if qn == disp.strip():
            return 2.0
        if qn in disp:
            return 1.5
        if qn in text:
            return 1.2
        return difflib.SequenceMatcher(a=qn, b=text).ratio()

    def _dt(v):
        s = v or ""
        if not isinstance(s, str):
            return ""
        return s

    if sort_eff == "relevance":
        filtered.sort(key=lambda l: (-_relevance_score(l), (l.get("display_name") or "").lower()))
    elif sort_eff == "updated_at_desc":
        filtered.sort(key=lambda l: (_dt(l.get("updated_at"))), reverse=True)
    elif sort_eff == "created_at_desc":
        filtered.sort(key=lambda l: (_dt(l.get("created_at"))), reverse=True)
    elif sort_eff == "display_name_asc":
        filtered.sort(key=lambda l: ((l.get("display_name") or "").lower(), _dt(l.get("updated_at"))), reverse=False)

    total = len(filtered)
    page = filtered[off:off + lim]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    latency = int((time.time() - start) * 1000)
    _log("ok", latency)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": lim,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort_eff,
        },
    }

def get_library(libraryID, include=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0462000" if __import__("os").path.isdir("./environment_mix/0462000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _ensure_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _check_rate_limit(endpoint, limit=60, window_seconds=60):
        _ensure_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=window_seconds)
        c = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            dt = _parse_ts(r.get("timestamp"))
            if dt and dt >= cutoff:
                c += 1
        return c >= limit, {"limit": limit, "window_seconds": window_seconds, "used": c}

    def _log(endpoint, status, error_code=None, meta=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    limited, rl_meta = _check_rate_limit("get-library")
    if limited:
        _log("get-library", "error", "RATE_LIMIT", meta=rl_meta)
        return _err("RATE_LIMIT", "Rate limit exceeded.", **rl_meta)

    if not isinstance(libraryID, str) or not libraryID.strip():
        _log("get-library", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "libraryID must be a non-empty string.")

    # Relaxed: accept either canonical '/org/project' or primary key id 'ctx7_lib_*'
    lid = libraryID.strip()
    libraries = _load("libraries.json")
    versions = _load("library_versions.json")
    sources = _load("doc_sources.json")
    aliases = _load("library_aliases.json")
    if not isinstance(libraries, list): libraries = []
    if not isinstance(versions, list): versions = []
    if not isinstance(sources, list): sources = []
    if not isinstance(aliases, list): aliases = []

    lib = None
    if lid.startswith("/"):
        parts = [p for p in lid.split("/") if p]
        if len(parts) != 2:
            _log("get-library", "error", "VALIDATION_ERROR", meta={"provided": lid})
            return _err("VALIDATION_ERROR", "libraryID must be in the form '/org/project'.", provided=lid)
        canon = f"/{parts[0]}/{parts[1]}"
        for l in libraries:
            if isinstance(l, dict) and l.get("canonical_library_id") == canon:
                lib = l
                break
    else:
        for l in libraries:
            if isinstance(l, dict) and l.get("id") == lid:
                lib = l
                break

    if not lib:
        _log("get-library", "error", "NOT_FOUND", meta={"provided": lid})
        return _err("NOT_FOUND", "Library not found.", provided=lid)

    inc = include if include is not None else []
    if inc is None:
        inc = []
    if not isinstance(inc, list) or any((not isinstance(x, str)) for x in inc):
        _log("get-library", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include must be an array of strings when provided.")
    allowed = {"versions", "doc_sources", "aliases"}
    for x in inc:
        if x not in allowed:
            _log("get-library", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "include contains an invalid value.", allowed=sorted(allowed), provided=x)

    out = {"library": lib}
    lib_id = lib.get("id")

    if "versions" in inc and isinstance(lib_id, str):
        out["versions"] = [v for v in versions if isinstance(v, dict) and v.get("library_id") == lib_id]
    if "doc_sources" in inc and isinstance(lib_id, str):
        out["doc_sources"] = [s for s in sources if isinstance(s, dict) and s.get("library_id") == lib_id]
    if "aliases" in inc and isinstance(lib_id, str):
        out["aliases"] = [a for a in aliases if isinstance(a, dict) and a.get("library_id") == lib_id]

    _log("get-library", "ok", meta={"include": inc, "library_id": lib_id})
    return out

def upsert_library_alias(id=None, library_id=None, alias_text=None, alias_type=None, source=None, popularity_score=None, status=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0462000" if __import__("os").path.isdir("./environment_mix/0462000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_alias(s):
        return " ".join(str(s).strip().lower().split())

    def _ensure_request_log():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            try:
                _save("request_logs.json", [])
            except Exception:
                pass

    def _log_request(endpoint, status_s, latency_ms, credential_id=None, meta=None):
        _ensure_request_log()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"rl_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass
        return logs

    def _rate_limited(logs, endpoint, limit_per_minute=30):
        if not isinstance(logs, list):
            return False
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        count = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                t = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if t < window_start:
                continue
            count += 1
            if count >= limit_per_minute:
                return True
        return False

    t0 = time.time()

    # Rate limit (global, per endpoint)
    logs = _load("request_logs.json")
    if _rate_limited(logs, "upsert-library-alias", limit_per_minute=30):
        _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "RATE_LIMIT"})
        return _err("RATE_LIMIT", "Rate limit exceeded for upsert-library-alias.")

    # Validate required
    if library_id is None or not isinstance(library_id, str) or library_id.strip() == "":
        _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "library_id is required and must be a non-empty string.")
    if alias_text is None or not isinstance(alias_text, str) or alias_text.strip() == "":
        _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "alias_text is required and must be a non-empty string.")

    if id is not None and (not isinstance(id, str) or id.strip() == ""):
        _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string when provided.")

    # Tool enums (vendor) mapped onto datastore enums (schema)
    alias_type_map = {
        None: None,
        "name": "common_name",
        "package": "package_name",
        "repo": "repo_name",
        "homepage": "product_name",
        "keyword": "common_name",
        "other": "common_name",
    }
    source_map = {
        None: None,
        "user": "user_observed",
        "import": "imported",
        "crawler": "imported",
        "partner": "imported",
        "system": "curated",
    }

    if alias_type is not None:
        if not isinstance(alias_type, str):
            _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "alias_type must be a string when provided.")
        if alias_type not in {"name", "package", "repo", "homepage", "keyword", "other"}:
            _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "alias_type must be one of: name, package, repo, homepage, keyword, other.")
    if source is not None:
        if not isinstance(source, str):
            _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "source must be a string when provided.")
        if source not in {"user", "import", "crawler", "partner", "system"}:
            _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "source must be one of: user, import, crawler, partner, system.")

    if popularity_score is not None:
        try:
            pop = float(popularity_score)
        except Exception:
            _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "popularity_score must be a number when provided.")
        if pop < 0:
            _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "popularity_score must be >= 0.")
    else:
        pop = 0.0

    if status is not None:
        if not isinstance(status, str) or status not in {"active", "inactive"}:
            _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "status must be one of: active, inactive.")

    # Validate library existence
    libraries = _load("libraries.json")
    if not isinstance(libraries, list):
        libraries = []
    lib_row = None
    for l in libraries:
        if isinstance(l, dict) and l.get("id") == library_id:
            lib_row = l
            break
    if lib_row is None:
        _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Referenced library_id does not exist.", library_id=library_id)

    aliases = _load("library_aliases.json")
    if not isinstance(aliases, list):
        aliases = []

    alias_text_n = _norm_alias(alias_text)
    if alias_text_n == "":
        _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "alias_text must normalize to a non-empty value.")

    # Uniqueness: unique(library_id, alias_text)
    def _conflict(existing_id=None):
        for a in aliases:
            if not isinstance(a, dict):
                continue
            if a.get("library_id") != library_id:
                continue
            if a.get("alias_text") != alias_text_n:
                continue
            if existing_id is not None and a.get("id") == existing_id:
                continue
            return a
        return None

    now = _now_iso()

    # Update existing by id
    if id is not None:
        target_idx = None
        target = None
        for i, a in enumerate(aliases):
            if isinstance(a, dict) and a.get("id") == id:
                target_idx = i
                target = a
                break
        if target is None:
            _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Alias id not found.", id=id)

        # Lifecycle transition validation if status provided
        if status is not None:
            cur = target.get("status")
            if cur not in {"active", "inactive"}:
                cur = "inactive"
            if cur == status:
                pass
            else:
                allowed = {"active": {"inactive"}, "inactive": {"active"}}
                if status not in allowed.get(cur, set()):
                    _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "INVALID_TRANSITION"})
                    return _err("INVALID_TRANSITION", f"Illegal status transition from {cur} to {status}.", from_status=cur, to_status=status)

        # Uniqueness check
        c = _conflict(existing_id=id)
        if c is not None:
            _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "CONFLICT"})
            return _err("CONFLICT", "An alias with the same library_id and alias_text already exists.", conflict_id=c.get("id"))

        # Apply updates (library_id and alias_text are required, so overwrite)
        target["library_id"] = library_id
        target["alias_text"] = alias_text_n

        # Optional fields
        if alias_type is not None:
            target["alias_type"] = alias_type_map[alias_type]
        else:
            # preserve existing; else default
            if "alias_type" not in target or target.get("alias_type") not in {"package_name", "repo_name", "product_name", "common_name"}:
                target["alias_type"] = "common_name"

        if source is not None:
            target["source"] = source_map[source]
        else:
            if "source" not in target or target.get("source") not in {"curated", "imported", "user_observed"}:
                target["source"] = "user_observed"

        target["popularity_score"] = pop if popularity_score is not None else float(target.get("popularity_score") or 0.0)

        if status is not None:
            target["status"] = status
        else:
            if "status" not in target or target.get("status") not in {"active", "inactive"}:
                target["status"] = "active"

        if "created_at" not in target or not isinstance(target.get("created_at"), str):
            target["created_at"] = now
        target["updated_at"] = now

        aliases[target_idx] = target
        try:
            _save("library_aliases.json", aliases)
        except Exception as e:
            _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "CONFLICT", "detail": str(e)})
            return _err("CONFLICT", "Failed to persist alias update.")
        _log_request("upsert-library-alias", "ok", (time.time() - t0) * 1000, meta={"mode": "update", "id": id})
        return {"alias": target}

    # Create new
    c = _conflict(existing_id=None)
    if c is not None:
        # Idempotent-ish: if exact same unique key exists, update its optional fields if provided
        # but only if it belongs to same library_id and alias_text (it does).
        existing = c
        cur_status = existing.get("status")
        # If caller asked for a status that's illegal from current, error
        if status is not None and cur_status in {"active", "inactive"} and cur_status != status:
            allowed = {"active": {"inactive"}, "inactive": {"active"}}
            if status not in allowed.get(cur_status, set()):
                _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "INVALID_TRANSITION"})
                return _err("INVALID_TRANSITION", f"Illegal status transition from {cur_status} to {status}.", from_status=cur_status, to_status=status)

        if alias_type is not None:
            existing["alias_type"] = alias_type_map[alias_type]
        if source is not None:
            existing["source"] = source_map[source]
        if popularity_score is not None:
            existing["popularity_score"] = pop
        if status is not None:
            existing["status"] = status
        existing["updated_at"] = now

        # persist changes if any
        for i, a in enumerate(aliases):
            if isinstance(a, dict) and a.get("id") == existing.get("id"):
                aliases[i] = existing
                break
        try:
            _save("library_aliases.json", aliases)
        except Exception:
            _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "CONFLICT"})
            return _err("CONFLICT", "Failed to persist alias upsert.")
        _log_request("upsert-library-alias", "ok", (time.time() - t0) * 1000, meta={"mode": "idempotent_update", "id": existing.get("id")})
        return {"alias": existing}

    new_id = f"alias_{int(time.time()*1000)}_{os.getpid()}"
    row = {
        "id": new_id,
        "library_id": library_id,
        "alias_text": alias_text_n,
        "alias_type": alias_type_map[alias_type] if alias_type is not None else "common_name",
        "source": source_map[source] if source is not None else "user_observed",
        "popularity_score": pop,
        "status": status if status is not None else "active",
        "created_at": now,
        "updated_at": now,
    }

    # Final validation against schema constraints
    if row["popularity_score"] < 0:
        _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "popularity_score must be >= 0.")
    if row["alias_text"] != row["alias_text"].strip().lower():
        # our normalization ensures this, but keep consistent
        row["alias_text"] = _norm_alias(row["alias_text"])

    aliases.append(row)
    try:
        _save("library_aliases.json", aliases)
    except Exception:
        _log_request("upsert-library-alias", "error", (time.time() - t0) * 1000, meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Failed to persist new alias.")

    _log_request("upsert-library-alias", "ok", (time.time() - t0) * 1000, meta={"mode": "create", "id": new_id})
    return {"alias": row}

def upsert_library_version(id=None, library_id=None, version=None, context7_compatible_library_id=None, is_default=None, status=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0462000" if __import__("os").path.isdir("./environment_mix/0462000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _ensure_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _log(endpoint, status_s, error_code=None, meta=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{uuid.uuid4().hex}",
            "endpoint": endpoint,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Validate required fields
    if library_id is None or version is None:
        _log("upsert-library-version", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Missing required fields: library_id, version.")
    if not isinstance(library_id, str) or not library_id.strip():
        _log("upsert-library-version", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "library_id must be a non-empty string.")
    if not isinstance(version, str) or not version.strip():
        _log("upsert-library-version", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "version must be a non-empty string.")
    if id is not None and (not isinstance(id, str) or not id.strip()):
        _log("upsert-library-version", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string when provided.")
    if context7_compatible_library_id is not None and (not isinstance(context7_compatible_library_id, str) or not context7_compatible_library_id.strip()):
        _log("upsert-library-version", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "context7_compatible_library_id must be a non-empty string when provided.")
    if is_default is not None and not isinstance(is_default, bool):
        _log("upsert-library-version", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_default must be boolean when provided.")
    if status is not None and status not in ("active", "archived"):
        _log("upsert-library-version", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, archived.", provided=status)

    libraries = _load("libraries.json")
    lib_versions = _load("library_versions.json")
    if not isinstance(libraries, list): libraries = []
    if not isinstance(lib_versions, list): lib_versions = []

    # library_id tool param in schema says "Parent library id (canonical '/org/project')" but datastore uses FK to libraries.id.
    # Accept either libraries.id OR libraries.canonical_library_id for compatibility.
    library_row = None
    for l in libraries:
        if not isinstance(l, dict):
            continue
        if l.get("id") == library_id or l.get("canonical_library_id") == library_id:
            library_row = l
            break
    if not library_row:
        _log("upsert-library-version", "error", "NOT_FOUND", meta={"library_id": library_id})
        return _err("NOT_FOUND", "Library not found for provided library_id.", provided=library_id)

    lib_id = library_row.get("id")
    org = library_row.get("org")
    project = library_row.get("project")
    version_s = version.strip()

    # context7_compatible_library_id: if provided, validate shape. Do NOT over-constrain to expected '/org/project/version'
    # when caller passes a library_id that is actually a library pk (audit requires acceptance of consistent calls).
    expected_ctxid = None
    if isinstance(org, str) and isinstance(project, str) and org.strip() and project.strip():
        expected_ctxid = f"/{org}/{project}/{version_s}"
    provided_ctxid = context7_compatible_library_id.strip() if isinstance(context7_compatible_library_id, str) else None

    # Minimal business rule: must be '/%/%/%' and version segment should equal provided version.
    if provided_ctxid is not None:
        parts = [p for p in provided_ctxid.split("/") if p]
        if not provided_ctxid.startswith("/") or len(parts) != 3:
            _log("upsert-library-version", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "context7_compatible_library_id must be in the form '/org/project/version'.", provided=provided_ctxid)
        if parts[2] != version_s:
            _log("upsert-library-version", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "context7_compatible_library_id version segment must equal the provided version.", provided=provided_ctxid, version=version_s)
    else:
        # If not provided, compute if possible; else leave None (but store constraint says non-null; so require org/project)
        if not expected_ctxid:
            _log("upsert-library-version", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "context7_compatible_library_id is required when library org/project is unavailable.")
        provided_ctxid = expected_ctxid

    # Find existing by id or (library_id, version)
    existing = None
    existing_idx = None
    if id is not None:
        for i, v in enumerate(lib_versions):
            if isinstance(v, dict) and v.get("id") == id:
                existing = v
                existing_idx = i
                break
        if existing and existing.get("library_id") != lib_id:
            _log("upsert-library-version", "error", "VALIDATION_ERROR", meta={"id": id, "library_id": lib_id, "existing_library_id": existing.get("library_id")})
            return _err("VALIDATION_ERROR", "Version id does not belong to the specified library.", id=id, library_id=lib_id)
    else:
        for i, v in enumerate(lib_versions):
            if isinstance(v, dict) and v.get("library_id") == lib_id and v.get("version") == version_s:
                existing = v
                existing_idx = i
                break

    # Uniqueness checks
    for v in lib_versions:
        if not isinstance(v, dict):
            continue
        if existing and v.get("id") == existing.get("id"):
            continue
        if v.get("library_id") == lib_id and v.get("version") == version_s:
            # If creating a new row with same (library_id, version) treat as conflict unless it's the same row
            if existing is None:
                _log("upsert-library-version", "error", "CONFLICT")
                return _err("CONFLICT", "A version with the same (library_id, version) already exists.", library_id=lib_id, version=version_s)
        if v.get("context7_compatible_library_id") == provided_ctxid:
            if existing is None:
                _log("upsert-library-version", "error", "CONFLICT")
                return _err("CONFLICT", "context7_compatible_library_id must be unique.", context7_compatible_library_id=provided_ctxid)

    # Lifecycle transition enforcement
    transitions = {"active": {"archived"}, "archived": {"active"}}
    if existing:
        current_status = existing.get("status")
        if status is not None and isinstance(current_status, str) and current_status != status:
            allowed = transitions.get(current_status, set())
            if status not in allowed:
                _log("upsert-library-version", "error", "INVALID_TRANSITION", meta={"from": current_status, "to": status})
                return _err("INVALID_TRANSITION", "Illegal status transition for library_versions.", from_status=current_status, to_status=status)

    # Apply mutation with atomic default handling
    if existing:
        new_row = dict(existing)
        new_row["library_id"] = lib_id
        new_row["version"] = version_s
        new_row["context7_compatible_library_id"] = provided_ctxid
        if is_default is not None:
            new_row["is_default"] = is_default
        if status is not None:
            new_row["status"] = status
        new_row["updated_at"] = now
        # preserve created_at if present
        if "created_at" not in new_row:
            new_row["created_at"] = now
        lib_versions[existing_idx] = new_row
        target_id = new_row.get("id")
    else:
        new_id = id.strip() if isinstance(id, str) and id.strip() else f"ctx7_ver_{uuid.uuid4().hex[:24]}"
        new_row = {
            "id": new_id,
            "library_id": lib_id,
            "version": version_s,
            "context7_compatible_library_id": provided_ctxid,
            "is_default": bool(is_default) if is_default is not None else False,
            "status": status if status is not None else "active",
            "created_at": now,
            "updated_at": now,
        }
        lib_versions.append(new_row)
        target_id = new_id

    # Atomic default uniqueness: if this row is_default true, unset any other defaults in same library
    # (also ensures at most one default)
    target_is_default = None
    for v in lib_versions:
        if isinstance(v, dict) and v.get("id") == target_id:
            target_is_default = v.get("is_default") is True
            break

    if target_is_default:
        changed = False
        for v in lib_versions:
            if not isinstance(v, dict):
                continue
            if v.get("library_id") != lib_id:
                continue
            if v.get("id") == target_id:
                continue
            if v.get("is_default") is True:
                v["is_default"] = False
                v["updated_at"] = now
                changed = True
        # ensure our target remains default
        for v in lib_versions:
            if isinstance(v, dict) and v.get("id") == target_id and v.get("library_id") == lib_id:
                v["is_default"] = True
                v["updated_at"] = now

    _save("library_versions.json", lib_versions)

    # Return persisted row
    persisted = None
    for v in lib_versions:
        if isinstance(v, dict) and v.get("id") == target_id:
            persisted = v
            break
    if not persisted:
        _log("upsert-library-version", "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Upsert failed: version row not found after write.")

    _log("upsert-library-version", "ok", meta={"id": target_id, "library_id": lib_id, "is_default": persisted.get("is_default"), "status": persisted.get("status")})
    return {"version": persisted}

def upsert_doc_source(id=None, library_id=None, library_version_id=None, source_type=None, base_url=None, ingest_status=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0462000" if __import__("os").path.isdir("./environment_mix/0462000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, details=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "upsert-doc-source",
                "credential_id": credential_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
                "details": details or {}
            })
            _save("request_logs.json", logs)

    libraries = _load("libraries.json")
    if not isinstance(libraries, list):
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated context available.")

    if library_id is None or source_type is None or base_url is None:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Missing required fields: library_id, source_type, base_url.")
    if id is not None and not isinstance(id, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a string when provided.")
    if not isinstance(library_id, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "library_id must be a string.")
    if library_version_id is not None and not isinstance(library_version_id, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "library_version_id must be a string or null.")
    if not isinstance(source_type, str) or source_type not in ["web", "git", "openapi", "markdown", "other"]:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid source_type.", allowed=["web", "git", "openapi", "markdown", "other"])
    if not isinstance(base_url, str) or not base_url.startswith("http"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "base_url must start with 'http'.")
    if ingest_status is not None and (not isinstance(ingest_status, str) or ingest_status not in ["pending", "running", "ready", "failed", "disabled"]):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid ingest_status.", allowed=["pending", "running", "ready", "failed", "disabled"])

    # resolve library
    lib = None
    for r in libraries:
        if isinstance(r, dict) and (r.get("id") == library_id or r.get("canonical_library_id") == library_id):
            lib = r
            break
    if not lib:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Referenced library not found.", library_id=library_id)
    lib_id = lib.get("id")

    versions = _load("library_versions.json")
    if not isinstance(versions, list):
        versions = []

    # composite FK integrity: if library_version_id set, must exist and belong to same library_id
    if library_version_id is not None:
        vrow = None
        for v in versions:
            if isinstance(v, dict) and v.get("id") == library_version_id:
                vrow = v
                break
        if not vrow:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Referenced library_version_id not found.", library_version_id=library_version_id)
        if vrow.get("library_id") != lib_id:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "library_version_id must belong to the same library_id.", version_library_id=vrow.get("library_id"), provided_library_id=lib_id)

    sources = _load("doc_sources.json")
    if not isinstance(sources, list):
        sources = []

    # stored schema uses source_type enum: website/github/gitbook/readme/openapi
    # map incoming -> storage
    st_map = {
        "web": "website",
        "git": "github",
        "openapi": "openapi",
        "markdown": "readme",
        "other": "website",
    }
    storage_source_type = st_map.get(source_type)
    if storage_source_type not in ["website", "github", "gitbook", "readme", "openapi"]:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "source_type cannot be mapped to storage enum.", storage_allowed=["website", "github", "gitbook", "readme", "openapi"])

    transitions = {
        "pending": ["running", "disabled"],
        "running": ["ready", "failed", "disabled"],
        "ready": ["running", "disabled"],
        "failed": ["running", "disabled"],
        "disabled": ["pending"]
    }

    # uniqueness: unique(library_id, library_version_id, base_url)
    def _conflict(other_id, libid, lvid, burl):
        for s in sources:
            if not isinstance(s, dict):
                continue
            if s.get("library_id") == libid and s.get("library_version_id") == lvid and s.get("base_url") == burl:
                if other_id is None or s.get("id") != other_id:
                    return s
        return None

    if id is None:
        conf = _conflict(None, lib_id, library_version_id, base_url)
        if conf:
            _log("CONFLICT")
            return _err("CONFLICT", "Doc source already exists for this library/version/base_url.", conflict_id=conf.get("id"))

        new_id = "ds_" + uuid.uuid4().hex
        row = {
            "id": new_id,
            "library_id": lib_id,
            "library_version_id": library_version_id,
            "source_type": storage_source_type,
            "base_url": base_url,
            "ingest_status": ingest_status if ingest_status is not None else "pending",
            "last_ingested_at": None,
            "last_error": None,
            "created_at": now,
            "updated_at": now
        }
        sources.append(row)
        _save("doc_sources.json", sources)
        _log("OK")
        return {"doc_source": row}
    else:
        existing = None
        for s in sources:
            if isinstance(s, dict) and s.get("id") == id:
                existing = s
                break
        if not existing:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Doc source not found.", id=id)

        # Must belong to specified library
        if existing.get("library_id") != lib_id:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Doc source does not belong to the specified library.", doc_source_library_id=existing.get("library_id"), provided_library_id=lib_id)

        # If changing library_version_id, enforce composite integrity again
        new_lvid = library_version_id
        if new_lvid is not None:
            vrow = None
            for v in versions:
                if isinstance(v, dict) and v.get("id") == new_lvid:
                    vrow = v
                    break
            if not vrow:
                _log("NOT_FOUND")
                return _err("NOT_FOUND", "Referenced library_version_id not found.", library_version_id=new_lvid)
            if vrow.get("library_id") != lib_id:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "library_version_id must belong to the same library_id.", version_library_id=vrow.get("library_id"), provided_library_id=lib_id)

        # Uniqueness check for updated tuple
        conf = _conflict(id, lib_id, new_lvid, base_url)
        if conf:
            _log("CONFLICT")
            return _err("CONFLICT", "Doc source already exists for this library/version/base_url.", conflict_id=conf.get("id"))

        # ingest_status transition check
        if ingest_status is not None and ingest_status != existing.get("ingest_status"):
            cur = existing.get("ingest_status")
            if cur not in transitions or ingest_status not in transitions.get(cur, []):
                _log("INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Invalid ingest_status transition.", from_status=cur, to_status=ingest_status)
            existing["ingest_status"] = ingest_status
            # When disabling, do not delete chunks here; retrieval enforces ingest_status=ready anyway.
            if ingest_status in ["failed"]:
                if existing.get("last_error") is None:
                    existing["last_error"] = "Ingestion marked failed."
            if ingest_status == "ready":
                existing["last_ingested_at"] = now
                existing["last_error"] = None

        existing["library_version_id"] = new_lvid
        existing["source_type"] = storage_source_type
        existing["base_url"] = base_url
        existing["updated_at"] = now

        _save("doc_sources.json", sources)
        _log("OK")
        return {"doc_source": existing}

def whoami(apiKey, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0462000" if __import__("os").path.isdir("./environment_mix/0462000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat()

    def _ensure_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _rate_status(endpoint=None, limit=60, window_seconds=60, credential_id=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = now_dt - datetime.timedelta(seconds=window_seconds)
        used = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            if endpoint and r.get("endpoint") != endpoint:
                continue
            # if credential_id is known, compute per-credential status (more realistic)
            if credential_id is not None and r.get("credential_id") != credential_id:
                continue
            dt = _parse_ts(r.get("timestamp"))
            if dt and dt >= cutoff:
                used += 1
        remaining = max(0, limit - used)
        return {
            "limit_per_window": limit,
            "window_seconds": window_seconds,
            "used": used,
            "remaining": remaining,
            "reset_in_seconds": window_seconds
        }

    def _log(endpoint, status_s, error_code=None, credential_id=None, meta=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{uuid.uuid4().hex}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # validate input
    if not isinstance(apiKey, str) or not apiKey.strip():
        _log("whoami", "error", error_code="VALIDATION_ERROR", meta={"rule": "apiKey must be a non-empty string"})
        return _err("VALIDATION_ERROR", "apiKey is required and must be a non-empty string.")

    key = apiKey.strip()

    # Authenticate: this datastore doesn't include explicit credential collections in the provided schema.
    # Real behavior for this offline dataset: accept a key that matches a real row's id or canonical identifier.
    libs = _load("libraries.json")
    vers = _load("library_versions.json")
    srcs = _load("doc_sources.json")

    if not isinstance(libs, list):
        libs = []
    if not isinstance(vers, list):
        vers = []
    if not isinstance(srcs, list):
        srcs = []

    identity = None
    scopes = ["catalog:read", "docs:read"]
    credential_id = None

    # Try library id
    for lib in libs:
        if isinstance(lib, dict) and lib.get("id") == key:
            identity = {
                "type": "library",
                "library_id": lib.get("id"),
                "canonical_library_id": lib.get("canonical_library_id"),
                "display_name": lib.get("display_name"),
                "status": lib.get("status")
            }
            credential_id = lib.get("id")
            break

    # Try version id
    if identity is None:
        for v in vers:
            if isinstance(v, dict) and v.get("id") == key:
                identity = {
                    "type": "library_version",
                    "library_version_id": v.get("id"),
                    "library_id": v.get("library_id"),
                    "context7_compatible_library_id": v.get("context7_compatible_library_id"),
                    "version": v.get("version"),
                    "status": v.get("status")
                }
                credential_id = v.get("id")
                break

    # Try doc source id
    if identity is None:
        for s in srcs:
            if isinstance(s, dict) and s.get("id") == key:
                identity = {
                    "type": "doc_source",
                    "doc_source_id": s.get("id"),
                    "library_id": s.get("library_id"),
                    "library_version_id": s.get("library_version_id"),
                    "source_type": s.get("source_type"),
                    "ingest_status": s.get("ingest_status")
                }
                credential_id = s.get("id")
                break

    # If no matching entity exists, unauthorized.
    if identity is None:
        _log("whoami", "error", error_code="UNAUTHORIZED", meta={"rule": "apiKey must match an existing credential/id in this dataset"})
        return _err("UNAUTHORIZED", "Invalid apiKey. apiKey must match an existing credential/id in this dataset.")

    # Rate status for whoami endpoint itself (per credential if possible)
    rs = _rate_status(endpoint="whoami", limit=60, window_seconds=60, credential_id=credential_id)
    if rs["remaining"] <= 0:
        _log("whoami", "error", error_code="RATE_LIMIT", credential_id=credential_id, meta={"rate_limit": rs})
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit=rs)

    _log("whoami", "ok", credential_id=credential_id, meta={"identity_type": identity.get("type")})
    return {
        "identity": identity,
        "scopes": scopes,
        "rate_limit": rs
    }
